```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name, count(*) n, round(avg(value),3) avg_cpu_cores, round(max(value),3) max_cpu_cores FROM abnormal_metrics WHERE metric='container.cpu.usage' AND service_name='search' GROUP BY 1",
          "claim": "In the incident window, search pod container CPU usage averages about 2.7 cores, peaking near 2.86."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name, count(*) n, round(avg(value),4) avg_cpu_cores, round(max(value),4) max_cpu_cores FROM normal_metrics WHERE metric='container.cpu.usage' AND service_name='search' GROUP BY 1",
          "claim": "In the normal period, the same search pod's container CPU usage averages about 0.006 cores."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, round(avg(value),2) avg_cpu_time FROM abnormal_metrics_sum WHERE metric='container.cpu.time' AND service_name='search' UNION ALL SELECT 'norm', round(avg(value),2) FROM normal_metrics_sum WHERE metric='container.cpu.time' AND service_name='search'",
          "claim": "Search cumulative container CPU time is about 455 in the incident versus about 80 normally, with no matching rise in request volume."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, count(*) n, round(quantile_cont(duration,0.5)/1e6,3) p50_ms, round(quantile_cont(duration,0.95)/1e6,3) p95_ms FROM abnormal_traces WHERE service_name='search' AND span_name='search.Search/Nearby' AND attr_span_kind='Server' UNION ALL SELECT 'norm', count(*), round(quantile_cont(duration,0.5)/1e6,3), round(quantile_cont(duration,0.95)/1e6,3) FROM normal_traces WHERE service_name='search' AND span_name='search.Search/Nearby' AND attr_span_kind='Server'",
          "claim": "Search's Nearby server spans, which frontend calls, are slightly faster in the incident (p50 about 3.2 ms vs 4.2 ms, p95 unchanged); the CPU fault did not measurably slow frontend-visible latency."
        }
      ]
    }
  ]
}
```

